<style>
.sso-page{--sso-ink:#14233b;--sso-muted:#6b7890;--sso-line:#e5eaf2;color:var(--sso-ink)}.sso-hero{position:relative;overflow:hidden;border-radius:20px;padding:26px;background:linear-gradient(120deg,#10283d,#174e70 62%,#256b80);color:#fff;box-shadow:0 16px 34px rgba(16,40,61,.18)}.sso-hero:after{content:"";position:absolute;width:240px;height:240px;right:-50px;top:-105px;border:1px solid rgba(255,255,255,.16);border-radius:50%;box-shadow:0 0 0 30px rgba(255,255,255,.04),0 0 0 62px rgba(255,255,255,.03)}.sso-widget,.sso-panel{background:#fff;border:1px solid var(--sso-line);border-radius:16px;box-shadow:0 8px 22px rgba(19,35,59,.045)}.sso-widget{padding:16px 18px;height:100%}.sso-label{font-size:12px;color:var(--sso-muted);text-transform:uppercase;letter-spacing:.07em}.sso-value{font-size:25px;font-weight:750}.sso-icon{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#eaf1fb;color:#2763a5;font-size:17px}.sso-panel{padding:18px}.sso-form-control{border:1px solid #d7dfeb;border-radius:10px;min-height:42px}.sso-client-row{border-bottom:1px solid #edf1f6}.sso-client-row:last-child{border-bottom:0}.sso-secret{border:1px solid #f4d27e;background:#fff9e8;border-radius:14px;padding:16px}.sso-secret-value{font-family:Consolas,monospace;word-break:break-all;background:#fff;border:1px solid #f0e4c2;border-radius:8px;padding:10px}.sso-empty{color:var(--sso-muted);padding:28px;text-align:center}
@media(max-width:767.98px){.sso-hero{padding:20px}.sso-panel{padding:14px}.sso-actions .btn{margin:2px}}
</style>
