    <div class="row mb-3">
        <div class="col-md-4 mb-2"><div class="sso-widget d-flex justify-content-between align-items-center"><div><div class="sso-label">Klien terdaftar</div><div class="sso-value" id="sso-total"><?= count($clients) ?></div></div><div class="sso-icon"><i class="fas fa-link"></i></div></div></div>
        <div class="col-md-4 mb-2"><div class="sso-widget d-flex justify-content-between align-items-center"><div><div class="sso-label">Integrasi aktif</div><div class="sso-value text-success" id="sso-active"><?= count(array_filter($clients, function($client){ return (int)$client['is_enabled'] === 1; })) ?></div></div><div class="sso-icon" style="background:#e9f7ef;color:#21864a"><i class="fas fa-check-circle"></i></div></div></div>
        <div class="col-md-4 mb-2"><div class="sso-widget d-flex justify-content-between align-items-center"><div><div class="sso-label">Integrasi nonaktif</div><div class="sso-value text-muted" id="sso-disabled"><?= count(array_filter($clients, function($client){ return (int)$client['is_enabled'] !== 1; })) ?></div></div><div class="sso-icon" style="background:#eef1f5;color:#6b7890"><i class="fas fa-pause-circle"></i></div></div></div>
    </div>
