        <?php if (!empty($secret_once)): ?><div class="font-weight-bold mb-2"><i class="fas fa-exclamation-triangle text-warning mr-1"></i>Secret untuk <?= html_escape($secret_once['app_code']) ?> hanya ditampilkan saat ini. Simpan di secret manager server klien.</div><div class="d-flex flex-column flex-md-row"><div class="sso-secret-value flex-grow-1" id="sso-secret-value"><?= html_escape($secret_once['secret']) ?></div><button type="button" class="btn btn-outline-dark ml-md-2 mt-2 mt-md-0" id="sso-copy"><i class="fas fa-copy mr-1"></i> Salin</button></div><?php endif ?>
    </div>
    <div class="sso-panel mb-3"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center"><div class="mb-2 mb-md-0"><h5 class="font-weight-bold mb-1">Kunci enkripsi SSO</h5><div class="small text-muted" id="sso-encryption-status"><?= $sso_key_configured ? 'Kunci aktif. Secret klien dienkripsi menggunakan kunci server yang tersimpan.' : 'Kunci belum tersedia. Buat kunci sebelum mendaftarkan atau merotasi secret.' ?></div></div><button type="button" class="btn btn-<?= $sso_key_configured ? 'outline-secondary' : 'primary' ?>" id="sso-generate-encryption-key" data-url="<?= base_url('admin/portal-sso-clients/generate-encryption-key') ?>" <?= $sso_key_configured ? 'disabled' : '' ?>><i class="fas fa-key mr-1"></i><?= $sso_key_configured ? 'Kunci sudah aktif' : 'Buat kunci otomatis' ?></button></div><div class="small text-muted mt-2">Kunci disimpan di konfigurasi lokal server dan tidak ditampilkan. Jangan hapus atau ganti berkas kunci setelah secret dibuat.</div></div>
    <div class="sso-panel mb-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><h5 class="font-weight-bold mb-1">Daftarkan klien</h5><div class="small text-muted">Callback harus HTTPS dan harus cocok persis dengan konfigurasi klien.</div></div><i class="fas fa-shield-alt text-info fa-lg"></i></div>
        <form id="sso-client-form" method="post" action="<?= base_url('admin/portal-sso-clients/save') ?>"><input type="hidden" name="form_token" value="<?= html_escape($form_token) ?>"><div class="form-row align-items-end">
            <div class="form-group col-md-3"><label for="app-code" class="font-weight-bold">Aplikasi</label><select class="form-control sso-form-control" id="app-code" name="app_code" required><?php foreach ($apps as $code => $app): ?><option value="<?= html_escape($code) ?>"><?= html_escape($app['name']) ?> · <?= html_escape($code) ?></option><?php endforeach ?></select></div>
            <div class="form-group col-md-7"><label for="redirect-uri" class="font-weight-bold">URL callback</label><input class="form-control sso-form-control" id="redirect-uri" name="redirect_uri" type="url" placeholder="https://aplikasi.example/sso/callback" required></div>
            <div class="form-group col-md-2"><button class="btn btn-primary btn-block" type="submit" id="sso-save"><i class="fas fa-save mr-1"></i> Simpan</button></div>
        </div></form>
    </div>
    <div class="sso-panel"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center mb-3"><div><h5 class="font-weight-bold mb-1">Daftar integrasi</h5><div class="small text-muted">Nonaktifkan klien untuk menghentikan penerbitan login baru.</div></div><div class="d-flex mt-2 mt-md-0"><input type="search" id="sso-search" class="form-control sso-form-control mr-2" placeholder="Cari aplikasi atau callback"><select id="sso-filter" class="form-control sso-form-control" style="width:135px"><option value="all">Semua status</option><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div></div>
        <div class="table-responsive"><table class="table table-hover align-middle mb-0" id="sso-table"><thead><tr><th>Aplikasi</th><th>Callback terdaftar</th><th>Status</th><th class="text-right">Aksi</th></tr></thead><tbody>
        <?php foreach ($clients as $client): $enabled = (int)$client['is_enabled'] === 1; ?><tr class="sso-client-row" data-app-code="<?= html_escape($client['app_code']) ?>" data-status="<?= $enabled ? '1' : '0' ?>">
            <td><div class="font-weight-bold"><?= html_escape($apps[$client['app_code']]['name'] ?? $client['app_code']) ?></div><code><?= html_escape($client['app_code']) ?></code></td><td class="text-break small"><?= html_escape($client['redirect_uri']) ?></td><td><span class="badge badge-<?= $enabled ? 'success' : 'secondary' ?> sso-status"><?= $enabled ? 'Aktif' : 'Nonaktif' ?></span></td>
            <td class="text-right text-nowrap sso-actions"><button type="button" class="btn btn-sm btn-outline-info sso-reveal" title="Lihat secret key" aria-label="Lihat secret key untuk <?= html_escape($client['app_code']) ?>" data-url="<?= base_url('admin/portal-sso-clients/reveal/' . rawurlencode($client['app_code'])) ?>"><i class="fas fa-key"></i></button> <button class="btn btn-sm btn-outline-<?= $enabled ? 'secondary' : 'success' ?> sso-toggle" data-url="<?= base_url('admin/portal-sso-clients/toggle/' . rawurlencode($client['app_code'])) ?>" data-enabled="<?= $enabled ? '0' : '1' ?>"><i class="fas fa-<?= $enabled ? 'pause' : 'play' ?> mr-1"></i><?= $enabled ? 'Nonaktifkan' : 'Aktifkan' ?></button><button class="btn btn-sm btn-outline-warning sso-rotate" data-url="<?= base_url('admin/portal-sso-clients/rotate/' . rawurlencode($client['app_code'])) ?>"><i class="fas fa-sync-alt mr-1"></i>Rotasi secret</button></td>
        </tr><?php endforeach ?>
        <?php if (empty($clients)): ?><tr id="sso-empty"><td colspan="4" class="sso-empty"><i class="fas fa-plug fa-2x d-block mb-2"></i>Belum ada aplikasi yang terhubung. Daftarkan klien pertama di atas.</td></tr><?php endif ?>
        </tbody></table></div>
    </div>
</section>
<div class="modal fade" id="sso-key-modal" tabindex="-1" role="dialog" aria-labelledby="sso-key-title" aria-hidden="true">
    <div class="modal-dialog modal-dialog-centered" role="document"><div class="modal-content border-0 shadow">
        <div class="modal-header"><div><h5 class="modal-title font-weight-bold" id="sso-key-title"><i class="fas fa-key text-info mr-2"></i>Lihat Secret Key</h5><div class="small text-muted" id="sso-key-app"></div></div><button type="button" class="close" data-dismiss="modal" aria-label="Tutup"><span aria-hidden="true">&times;</span></button></div>
        <div class="modal-body"><div id="sso-key-pin-area"><label for="sso-key-pin" class="font-weight-bold">PIN keamanan</label><input type="password" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="off" class="form-control sso-form-control" id="sso-key-pin" placeholder="Masukkan PIN 6 digit"><small class="text-muted">Secret hanya ditampilkan kepada administrator yang mengetahui PIN.</small></div><div id="sso-key-result" class="sso-secret-value mt-2" style="display:none"></div><div id="sso-key-error" class="small text-danger mt-2" role="alert"></div></div>
        <div class="modal-footer"><button type="button" class="btn btn-light" data-dismiss="modal">Tutup</button><button type="button" class="btn btn-outline-dark" id="sso-key-copy" style="display:none"><i class="fas fa-copy mr-1"></i>Salin</button><button type="button" class="btn btn-primary" id="sso-key-submit"><i class="fas fa-unlock-alt mr-1"></i>Tampilkan</button></div>
    </div></div>
</div>
<script>
$(function(){
    const apps=<?= json_encode($apps, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP) ?>;
    const base=<?= json_encode(base_url('admin/portal-sso-clients')) ?>;
    const esc=value=>$('<div>').text(String(value??'')).html();
    function updateStats(){const rows=$('#sso-table tbody tr.sso-client-row'),active=rows.filter('[data-status="1"]').length;$('#sso-total').text(rows.length);$('#sso-active').text(active);$('#sso-disabled').text(rows.length-active);}
    function refreshFilter(){const query=$('#sso-search').val().toLowerCase(),status=$('#sso-filter').val();$('#sso-table tbody tr.sso-client-row').each(function(){const matchesText=$(this).text().toLowerCase().includes(query),matchesStatus=status==='all'||String($(this).attr('data-status'))===status;$(this).toggle(matchesText&&matchesStatus);});}
    function showSecret(data){$('#sso-secret-box').show().html('<div class="font-weight-bold mb-2"><i class="fas fa-exclamation-triangle text-warning mr-1"></i>Secret baru untuk '+$('<div>').text(data.app_code).html()+'. Simpan di secret manager server klien; tampilan ulang tersedia melalui ikon key dan PIN admin.</div><div class="d-flex flex-column flex-md-row"><div class="sso-secret-value flex-grow-1" id="sso-secret-value"></div><button type="button" class="btn btn-outline-dark ml-md-2 mt-2 mt-md-0" id="sso-copy"><i class="fas fa-copy mr-1"></i> Salin</button></div>');$('#sso-secret-value').text(data.secret);window.scrollTo({top:0,behavior:'smooth'});}
    function updateToken(token){if(token)$('[name="form_token"]').val(token);}
    function upsertClient(data){const code=data.app_code,app=apps[code]||{name:code},enabled=true;let $row=$('#sso-table tbody tr[data-app-code="'+esc(code)+'"]');if(!$row.length){$row=$('<tr class="sso-client-row"></tr>').attr('data-app-code',code).append('<td><div class="font-weight-bold"></div><code></code></td><td class="text-break small"></td><td><span class="badge sso-status"></span></td><td class="text-right text-nowrap sso-actions"></td>');$('#sso-empty').remove();$('#sso-table tbody').append($row);}$row.attr('data-status','1');$row.find('td').eq(0).find('div').text(app.name);$row.find('td').eq(0).find('code').text(code);$row.find('td').eq(1).text(data.redirect_uri||$row.find('td').eq(1).text());$row.find('.sso-status').attr('class','badge badge-success sso-status').text('Aktif');$row.find('.sso-actions').html('<button type="button" class="btn btn-sm btn-outline-info sso-reveal" title="Lihat secret key" aria-label="Lihat secret key"><i class="fas fa-key"></i></button> <button class="btn btn-sm btn-outline-secondary sso-toggle" data-url="'+base+'/toggle/'+encodeURIComponent(code)+'" data-enabled="0"><i class="fas fa-pause mr-1"></i>Nonaktifkan</button> <button class="btn btn-sm btn-outline-warning sso-rotate" data-url="'+base+'/rotate/'+encodeURIComponent(code)+'"><i class="fas fa-sync-alt mr-1"></i>Rotasi secret</button>');$row.find('.sso-reveal').attr('data-url',base+'/reveal/'+encodeURIComponent(code));updateStats();refreshFilter();}
    function submitAction(url,data,button){const $button=$(button),old=$button.html();$button.prop('disabled',true).html('<i class="fas fa-circle-notch fa-spin"></i>');$.ajax({url:url,type:'POST',data:data,dataType:'json'}).done(function(res){updateToken(res.data&&res.data.form_token);if(!res.status){toastr.error(res.message);return;}toastr.success(res.message);if(res.data&&res.data.secret)showSecret(res.data);if(res.data&&res.data.encryption_key_configured){$('#sso-encryption-status').text('Kunci aktif. Secret klien dienkripsi menggunakan kunci server yang tersimpan.');$button.html('<i class="fas fa-key mr-1"></i>Kunci sudah aktif').removeClass('btn-primary').addClass('btn-outline-secondary').prop('disabled',true);}if(data.enabled!==undefined){const row=$button.closest('tr'),enabled=String(data.enabled)==='1';row.attr('data-status',enabled?'1':'0');row.find('.sso-status').attr('class','badge badge-'+(enabled?'success':'secondary')+' sso-status').text(enabled?'Aktif':'Nonaktif');$button.attr('data-enabled',enabled?'0':'1').data('enabled',enabled?'0':'1').toggleClass('btn-outline-secondary',enabled).toggleClass('btn-outline-success',!enabled).html('<i class="fas fa-'+(enabled?'pause':'play')+' mr-1"></i>'+(enabled?'Nonaktifkan':'Aktifkan'));refreshFilter();updateStats();}}).fail(function(xhr){toastr.error(xhr.responseJSON&&xhr.responseJSON.message?xhr.responseJSON.message:'Server tidak merespons.');}).always(function(){if($button.html().indexOf('fa-circle-notch')!==-1){$button.prop('disabled',false).html(old);}});}
    $('#sso-client-form').on('submit',function(event){event.preventDefault();const $button=$('#sso-save');$button.prop('disabled',true).html('<i class="fas fa-circle-notch fa-spin mr-1"></i>Menyimpan');$.ajax({url:this.action,type:'POST',data:$(this).serialize(),dataType:'json'}).done(function(res){updateToken(res.data&&res.data.form_token);if(!res.status){toastr.error(res.message);return;}toastr.success(res.message);if(res.data.secret){showSecret(res.data);upsertClient(res.data);}}).fail(function(){toastr.error('Server tidak merespons saat menyimpan klien.');}).always(function(){$button.prop('disabled',false).html('<i class="fas fa-save mr-1"></i> Simpan');});});
    $('#sso-generate-encryption-key').on('click',function(){const button=this;if(!window.confirm('Buat dan simpan kunci enkripsi permanen untuk server ini? Kunci ini tidak dapat diganti dari halaman ini.'))return;submitAction($(button).data('url'),{form_token:$('[name="form_token"]').first().val()},button);});
    $('#sso-table').on('click','.sso-toggle',function(){const button=this,enabled=$(this).data('enabled');submitAction($(this).data('url'),{form_token:$('[name="form_token"]').first().val(),enabled:enabled},button);});
    $('#sso-table').on('click','.sso-reveal',function(){$('#sso-key-modal').data('url',$(this).data('url')).data('app-code',$(this).closest('tr').data('app-code'));$('#sso-key-app').text($(this).closest('tr').find('td').eq(0).text().trim());$('#sso-key-pin-area').show();$('#sso-key-pin').val('').prop('disabled',false);$('#sso-key-result,#sso-key-copy').hide();$('#sso-key-error').text('');$('#sso-key-submit').show().prop('disabled',false).html('<i class="fas fa-unlock-alt mr-1"></i>Tampilkan');$('#sso-key-modal').modal('show');});
    $('#sso-key-submit').on('click',function(){const $button=$(this),$pin=$('#sso-key-pin');if(!$pin.val()){ $('#sso-key-error').text('PIN wajib diisi.');return;}$button.prop('disabled',true).html('<i class="fas fa-circle-notch fa-spin mr-1"></i>Memeriksa');$.ajax({url:$('#sso-key-modal').data('url'),type:'POST',data:{form_token:$('[name="form_token"]').first().val(),pin:$pin.val()},dataType:'json'}).done(function(res){updateToken(res.data&&res.data.form_token);if(!res.status){$('#sso-key-error').text(res.message||'PIN salah.');toastr.error(res.message||'PIN salah.');$pin.val('').trigger('focus');return;}$('#sso-key-error').text('');$('#sso-key-pin-area').hide();$('#sso-key-result').text(res.data.secret).show();$('#sso-key-copy').show();$button.hide();}).fail(function(xhr){updateToken(xhr.responseJSON&&xhr.responseJSON.data&&xhr.responseJSON.data.form_token);$('#sso-key-error').text(xhr.responseJSON&&xhr.responseJSON.message?xhr.responseJSON.message:'Server tidak merespons.');}).always(function(){$button.prop('disabled',false);if($button.is(':visible'))$button.html('<i class="fas fa-unlock-alt mr-1"></i>Tampilkan');});});
    $('#sso-table').on('click','.sso-rotate',function(){const button=this;if(!window.confirm('Secret lama langsung tidak berlaku. Lanjutkan rotasi?'))return;submitAction($(this).data('url'),{form_token:$('[name="form_token"]').first().val()},button);});
    $('#sso-search,#sso-filter').on('input change',refreshFilter);
    $(document).on('click','#sso-copy',function(){const secret=$('#sso-secret-value').text();if(navigator.clipboard)navigator.clipboard.writeText(secret).then(()=>toastr.success('Secret disalin.')).catch(()=>toastr.error('Gagal menyalin secret.'));else toastr.error('Clipboard tidak tersedia pada browser ini.');});
    $('#sso-key-copy').on('click',function(){const secret=$('#sso-key-result').text();if(navigator.clipboard)navigator.clipboard.writeText(secret).then(()=>toastr.success('Secret disalin.')).catch(()=>toastr.error('Gagal menyalin secret.'));else toastr.error('Clipboard tidak tersedia pada browser ini.');});
    $('#sso-key-modal').on('hidden.bs.modal',function(){$('#sso-key-result').text('').hide();$('#sso-key-pin').val('');});
    updateStats();
});
</script>
